    description: 'برون‌سپاری کامل فرایند فروش خارجی', descriptionEn: 'Complete outsourcing of foreign sales processes',
    icon: '🤝', isActive: true, price: { amount: 0, currency: 'IRR' }
  },
  { 
    id: 's3', 
    title: 'طراحی بسته‌بندی صادراتی', titleEn: 'Export Packaging Design',
    description: 'طراحی استاندارد برای بازارهای جهانی', descriptionEn: 'Standard design for global markets',
    icon: '📦', isActive: true, price: { amount: 30000000, currency: 'IRR' }
  }
];

const DEFAULT_PERSONNEL: Personnel[] = [
  { 
    id: 'p_master', 
    fullName: 'Master Admin', 
    roles: ['مدیر'], 
    email: 'master@export.com', 
    username: 'master', 
    password: 'MasterAdmin2024', 
    status: 'active',
    permissions: { canAssign: true, canViewCustomers: true, canViewTariffs: true, canViewAllTickets: true, canIssueInvoices: true }
  }
];

const INITIAL_CONFIG: AppConfig = {
  appTitle: 'پلتفرم جامع صادراتی',
  appTitleEn: 'Export Platform',
  appSubtitle: 'مشاوره، توسعه بازار و خدمات بازرگانی',
  appSubtitleEn: 'Consultancy, Market Development & Trade Services',
  formFields: [
    { id: 'f1', key: 'fullName', label: 'نام و نام خانوادگی', type: 'text', required: true, order: 1, isSystem: true },
    { id: 'f4', key: 'phoneNumber', label: 'شماره موبایل', type: 'tel', required: true, order: 4, isSystem: true },
    { id: 'f8', key: 'description', label: 'شرح درخواست', type: 'textarea', required: true, order: 9, isSystem: true },
  ],
  assignmentConfig: { mode: 'manual', serviceRoleMap: {} },
  enableWhatsappAlerts: false
};

const STORAGE_KEYS = { USER: 'crm_session_user', VIEW: 'crm_last_view', LAST_ACTIVE: 'crm_last_active' };
const INACTIVITY_TIMEOUT = 30 * 60 * 1000;

const App: React.FC = () => {
  const [view, setViewState] = useState<ViewState>('landing');
  const [lang, setLang] = useState<Language>('fa');
  const [tickets, setTickets] = useState<Ticket[]>([]);
  const [services, setServices] = useState<ServiceOption[]>(DEFAULT_SERVICES);
  const [personnel, setPersonnel] = useState<Personnel[]>(DEFAULT_PERSONNEL);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [messages, setMessages] = useState<InternalMessage[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [meetings, setMeetings] = useState<Meeting[]>([]);
  const [kpis, setKpis] = useState<KPI[]>([]);
  const [currentUser, setCurrentUser] = useState<Personnel | null>(null);
  const [appConfig, setAppConfig] = useState<AppConfig>(INITIAL_CONFIG);
  const [isLoadingData, setIsLoadingData] = useState(true);

  const t = DICTIONARY[lang];

  const setView = (newView: ViewState) => { setViewState(newView); localStorage.setItem(STORAGE_KEYS.VIEW, newView); };

  useEffect(() => {
    document.documentElement.lang = lang;
    document.documentElement.dir = lang === 'fa' ? 'rtl' : 'ltr';
  }, [lang]);

  useEffect(() => {
    const restoreSession = () => {
        const storedUser = localStorage.getItem(STORAGE_KEYS.USER);
        const storedView = localStorage.getItem(STORAGE_KEYS.VIEW);
        const lastActive = localStorage.getItem(STORAGE_KEYS.LAST_ACTIVE);
        const now = Date.now();
        if (storedUser && lastActive && now - parseInt(lastActive) <= INACTIVITY_TIMEOUT) {
            try {
                setCurrentUser(JSON.parse(storedUser));
                if (storedView) setViewState(storedView as ViewState);
            } catch (e) { handleLogout(); }
        }
    };
    restoreSession();
  }, []);

  useEffect(() => {
    const unsubTickets = subscribeToTickets((data) => { setTickets(data); setIsLoadingData(false); });
    const unsubCustomers = subscribeToCustomers(setCustomers);
    const unsubMessages = subscribeToMessages(setMessages);
    const unsubTasks = subscribeToTasks(setTasks);
    const unsubMeetings = subscribeToMeetings(setMeetings);
    const unsubKPIs = subscribeToKPIs(setKpis);
    const unsubSettings = subscribeToSettings(
      (cfg) => { if (cfg) setAppConfig(cfg); },
      (srv) => { if (srv) setServices(srv); },
      (ppl) => { if (ppl) setPersonnel(ppl); }
    );
    return () => { unsubTickets(); unsubCustomers(); unsubSettings(); unsubMessages(); unsubTasks(); unsubMeetings(); unsubKPIs(); };
  }, []);

  const calculateAssignee = useCallback((serviceIdOrTitle: string): string | undefined => {
      const config = appConfig.assignmentConfig;
      if (!config || config.mode === 'manual') return undefined;
      let targetRole = config.serviceRoleMap[serviceIdOrTitle];
      if (!targetRole) {
          const serviceObj = services.find(s => s.title === serviceIdOrTitle || s.id === serviceIdOrTitle);
          if (serviceObj) targetRole = config.serviceRoleMap[serviceObj.id];
      }
      if (!targetRole) return undefined;
      const eligibleStaff = personnel.filter(p => p.roles.includes(targetRole) && p.status === 'active');
      if (eligibleStaff.length === 0) return undefined;
      if (config.mode === 'random') return eligibleStaff[Math.floor(Math.random() * eligibleStaff.length)].id;
      if (config.mode === 'auto_load_balance') {
          const staffWorkload = eligibleStaff.map(staff => ({ id: staff.id, count: tickets.filter(t => t.assignedTo === staff.id && t.status !== TicketStatus.COMPLETED && t.status !== TicketStatus.CANCELLED).length }));
          staffWorkload.sort((a, b) => a.count - b.count);
          return staffWorkload[0].id;
      }
      return undefined;
  }, [appConfig.assignmentConfig, personnel, tickets, services]);

  const notifyStaffOnWhatsapp = (ticket: Ticket, staff: Personnel) => {
      if (!appConfig.enableWhatsappAlerts || !staff.whatsappNumber) return;
      const service = services.find(s => s.id === ticket.serviceId);
      const message = `🔔 *درخواست جدید در سامانه*\n\n👤 مشتری: ${ticket.customerName}\n💼 خدمت: ${service?.title || 'نامشخص'}\n📱 تلفن: ${ticket.phoneNumber}\n🆔 کد رهگیری: ${ticket.id}\n\nلطفاً جهت بررسی به پنل مدیریت مراجعه کنید.`;
      const encodedMsg = encodeURIComponent(message);
      const waUrl = `https://api.whatsapp.com/send?phone=${staff.whatsappNumber.replace(/\D/g, '')}&text=${encodedMsg}`;
      window.open(waUrl, '_blank');
  };

  const saveNewTicketToSystem = async (ticket: Ticket) => {
    let assignedTo = ticket.assignedTo;
    let assignmentNote: TimelineEntry | null = null;
    if (!assignedTo) {
        const autoAssignedId = calculateAssignee(ticket.serviceId);
        if (autoAssignedId) {
            assignedTo = autoAssignedId;
            const assignee = personnel.find(p => p.id === autoAssignedId);
            assignmentNote = { type: 'assignment', title: 'ارجاع هوشمند', description: `تیکت به صورت اتوماتیک به ${assignee?.fullName} ارجاع شد.`, actorName: 'سیستم', timestamp: new Date().toISOString(), visibility: 'internal' };
            if (assignee) notifyStaffOnWhatsapp(ticket, assignee);
        }
    }
    const initialTimeline: TimelineEntry[] = [{ type: 'creation', title: 'ثبت درخواست', description: 'درخواست در سامانه ثبت شد', timestamp: new Date().toISOString(), actorName: 'سیستم', visibility: 'public' }, ...(ticket.timeline || [])];
    if (assignmentNote) initialTimeline.push(assignmentNote);
    await saveTicketToCloud({ ...ticket, assignedTo, timeline: initialTimeline });
  };

  const handleNewTicket = async (ticketOrTickets: Ticket | Ticket[]) => {
     try {
         if (Array.isArray(ticketOrTickets)) { for (const t of ticketOrTickets) await saveNewTicketToSystem(t); }
         else await saveNewTicketToSystem(ticketOrTickets);
     } catch (e) { alert("خطا در ذخیره سازی."); }
  };

  const handleUpdateTicket = async (id: string, updates: Partial<Ticket>, actorName: string, actionNote?: string, visibility: 'public' | 'internal' = 'public') => {
    const currentTicket = tickets.find(t => t.id === id);
    let newEntry: TimelineEntry | null = null;
    if (actionNote) {
        newEntry = { type: updates.projectData ? 'project_update' : (updates.status ? 'status_change' : (updates.assignedTo ? 'assignment' : 'comment')), title: updates.status ? 'تغییر وضعیت' : (updates.assignedTo ? 'تغییر مسئول' : (updates.projectData ? 'بروزرسانی پروژه' : 'یادداشت')), description: actionNote, timestamp: new Date().toISOString(), actorName, visibility };
    }
    await updateTicketInCloud(id, { ...updates, timeline: newEntry ? [...(currentTicket?.timeline || []), newEntry] : currentTicket?.timeline });
  };

  const handleLogout = () => { setCurrentUser(null); setView('landing'); localStorage.removeItem(STORAGE_KEYS.USER); localStorage.removeItem(STORAGE_KEYS.VIEW); localStorage.removeItem(STORAGE_KEYS.LAST_ACTIVE); };
  const handleLogin = async (u: string, p: string): Promise<boolean> => {
    const user = personnel.find(person => person.username === u && person.password === p);
    if (user) { setCurrentUser(user); logSystemAction('LOGIN', 'System', 'ورود کاربر', user.fullName, user.id); localStorage.setItem(STORAGE_KEYS.USER, JSON.stringify(sanitizeData(user))); localStorage.setItem(STORAGE_KEYS.LAST_ACTIVE, Date.now().toString()); return true; }
    return false;
  };

  return (
    <div className={`min-h-screen bg-gray-50 flex flex-col font-sans ${lang === 'fa' ? 'font-vazir' : ''}`} dir={lang === 'fa' ? 'rtl' : 'ltr'}>
      <header className="bg-white border-b border-gray-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 h-20 flex items-center justify-between">
          <div className="flex items-center gap-3 cursor-pointer" onClick={() => setView('landing')}><div className="bg-indigo-600 text-white p-2 rounded-lg"><IconShield className="w-6 h-6" /></div><div><h1 className="text-xl font-bold">{lang === 'fa' ? appConfig.appTitle : appConfig.appTitleEn}</h1></div></div>
          <div className="flex items-center gap-4">
            <nav className="hidden md:flex gap-2">
              <button onClick={() => setView('new-ticket')} className={`px-4 py-2 rounded-lg ${view === 'new-ticket' ? 'bg-indigo-600 text-white' : 'text-gray-600'}`}>ثبت درخواست</button>
              <button onClick={() => setView('admin')} className={`px-4 py-2 rounded-lg ${view === 'admin' ? 'bg-indigo-600 text-white' : 'text-gray-600'}`}>پنل کارشناسان</button>
            </nav>
            <div className="flex border rounded-lg overflow-hidden bg-white"><button onClick={() => setLang('fa')} className={`px-3 py-1 text-xs ${lang === 'fa' ? 'bg-indigo-100' : ''}`}>FA</button><button onClick={() => setLang('en')} className={`px-3 py-1 text-xs ${lang === 'en' ? 'bg-indigo-100' : ''}`}>EN</button></div>
          </div>
        </div>
      </header>
      <main className="flex-grow p-4 md:p-8 max-w-7xl mx-auto w-full">
        {isLoadingData && view !== 'landing' ? (<div className="flex items-center justify-center h-64">در حال دریافت اطلاعات...</div>) : (
          <>
            {view === 'landing' && (<div className="text-center py-20"><h2 className="text-4xl font-black mb-6">{appConfig.landingHeroTitle}</h2><button onClick={() => setView('new-ticket')} className="px-8 py-4 bg-indigo-600 text-white rounded-xl font-bold shadow-xl">شروع خدمات</button></div>)}
            {view === 'new-ticket' && (<CustomerForm config={appConfig} services={services.filter(s => s.isActive)} onSubmit={handleNewTicket} onCancel={() => setView('landing')} onGoToTracking={() => setView('tracking')} lang={lang} />)}
            {view === 'tracking' && (<TrackingView tickets={tickets} services={services} lang={lang} />)}
            {view === 'admin' && (!currentUser ? (<LoginView onLogin={handleLogin} onBack={() => setView('landing')} />) : (<AdminDashboard lang={lang} currentUser={currentUser} tickets={tickets} services={services} personnel={personnel} customers={customers} messages={messages} tasks={tasks} meetings={meetings} kpis={kpis} config={appConfig} onCreateTicket={async (t) => handleNewTicket(t)} onUpdateTicket={handleUpdateTicket} onDeleteTicket={deleteTicketFromCloud} onUpdateServices={saveServicesToCloud} onUpdatePersonnel={savePersonnelToCloud} onUpdateCustomers={saveCustomersBulkToCloud} onEditCustomer={updateCustomerInCloud} onDeleteCustomer={deleteCustomerFromCloud} onUpdateConfig={saveAppConfigToCloud} onLogout={handleLogout} />))}
          </>
        )}
      </main>
    </div>
  );
};

export default App;
